files.style_config.toml:
[[keywords]]
words = ['BOLD']
style = { fg = "red", bold = true }

[[keywords]]
words = ['ITALIC']
style = { fg = "blue", italic = true }

files.pointer_config.toml:
[pointer]
number = { fg = "green" }
letter = { fg = "blue" }
x = { fg = "red" }

files.custom_config.toml:
[pointer]
number = { fg = "green" }
letter = { fg = "blue" }

[[keywords]]
words = ['custom_keyword']
style = { fg = "red" }

files.regex_config.toml:
[[regexps]]
regex = 'Started (.*)\.'
style = { fg = "red" }

[[regexps]]
regex = 'Stopped .*'
style = { fg = "magenta" }

files.keywords_config.toml:
[[keywords]]
words = ['CRITICAL', 'FATAL']
style = { fg = "red", bold = true }

[[keywords]]
words = ['SUCCESS', 'OK']
style = { fg = "green" }
